import { ComponentFixture, TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { Watchlist } from './watchlist';
import { WatchlistStore } from '../watchlist-store';
import { expectNoA11yViolations } from '../../testing/axe';

describe('Watchlist', () => {
  let component: Watchlist;
  let fixture: ComponentFixture<Watchlist>;
  let el: HTMLElement;
  let store: WatchlistStore;

  async function render() {
    fixture = TestBed.createComponent(Watchlist);
    component = fixture.componentInstance;
    el = fixture.nativeElement;
    await fixture.whenStable();
  }

  beforeEach(async () => {
    localStorage.clear();
    await TestBed.configureTestingModule({
      imports: [Watchlist],
      // Stub route so clicking a title link has somewhere to navigate
      providers: [provideRouter([{ path: 'movie/:id', children: [] }])],
    }).compileComponents();

    store = TestBed.inject(WatchlistStore);
    store.add({ id: 1, title: 'Movie 1', release_date: '2024-01-01', poster_path: null, overview: '' });
    store.add({ id: 2, title: 'Movie 2', release_date: '2024-02-01', poster_path: '/p.jpg', overview: '' });
    await render();
  });

  const items = () => el.querySelectorAll<HTMLLIElement>('.watchlist-item');
  const checkbox = (i = 0) => items()[i].querySelector<HTMLInputElement>('input[type="checkbox"]')!;
  const rowTitles = () => [...el.querySelectorAll('.title-link')].map(a => a.textContent!.trim());
  const isWatched = (id: number) => store.items().find(m => m.id === id)?.watched;

  it('should create', () => {
    expect(component).toBeTruthy();
  });

  it('labels each checkbox with its movie title', () => {
    expect(checkbox().getAttribute('aria-label')).toBe('Watched: Movie 1');
    expect(checkbox().checked).toBe(false);
  });

  // Re-targeted for the required unwatched-first order: once the clicked row's
  // movie is watched it re-sorts to the end, so its checkbox is no longer at
  // DOM index 0 afterwards (index 0 is then the still-unwatched Movie 2).
  it('toggles watched when the checkbox is clicked', async () => {
    checkbox().click(); // checkbox on the first row (Movie 1)
    await fixture.whenStable();

    // Exactly the clicked row's movie is checked, at its new position.
    expect(checkbox(1).checked).toBe(true);
    expect(checkbox(0).checked).toBe(false);
    expect(component.watchedCount()).toBe(1);
    expect(el.querySelector('.subtitle')?.textContent).toContain('1 of 2 watched');
  });

  // Re-targeted like the test above: the clicked row re-sorts to the end.
  it('toggles watched when blank space on the row is clicked', async () => {
    items()[0].click(); // first row (Movie 1)
    await fixture.whenStable();

    // Exactly the clicked row's movie is checked; the other row is untouched.
    expect(checkbox(1).checked).toBe(true);
    expect(checkbox(0).checked).toBe(false);
  });

  it('navigates via the title link without toggling watched', async () => {
    const link = items()[0].querySelector<HTMLAnchorElement>('a.title-link')!;
    expect(link.getAttribute('href')).toBe('/movie/1');

    link.click();
    await fixture.whenStable();
    expect(store.items()[0].watched).toBe(false);
  });

  it('removes a movie and announces it to screen readers', async () => {
    items()[0].querySelector<HTMLButtonElement>('.remove-btn')!.click();
    await fixture.whenStable();

    expect(items().length).toBe(1);
    expect(el.querySelector('[role="status"]')?.textContent).toContain('Removed Movie 1 from your watchlist');
  });

  it('shows an empty state with a link to search', async () => {
    store.remove(1);
    store.remove(2);
    await fixture.whenStable();

    expect(el.querySelector('.empty-state a')?.getAttribute('href')).toBe('/search');
  });

  it('has no axe accessibility violations', async () => {
    await expectNoA11yViolations(el);
  });

  it('has no axe accessibility violations when empty', async () => {
    store.remove(1);
    store.remove(2);
    await fixture.whenStable();
    await expectNoA11yViolations(el);
  });

  it('lists unwatched movies before watched ones', async () => {
    store.toggleWatched(1); // Movie 1 becomes watched
    await fixture.whenStable();

    const titles = [...el.querySelectorAll('.title-link')].map(a => a.textContent!.trim());
    expect(titles).toEqual(['Movie 2', 'Movie 1']);
  });

  it('keeps relative order within the unwatched and watched groups', async () => {
    store.add({ id: 3, title: 'Movie 3', release_date: '2024-03-01', poster_path: null, overview: '' });
    store.add({ id: 4, title: 'Movie 4', release_date: '2024-04-01', poster_path: null, overview: '' });
    store.toggleWatched(2);
    store.toggleWatched(4);
    await fixture.whenStable();

    const titles = [...el.querySelectorAll('.title-link')].map(a => a.textContent!.trim());
    expect(titles).toEqual(['Movie 1', 'Movie 3', 'Movie 2', 'Movie 4']);
  });

  it('preserves the store order and does not drop items', () => {
    expect(component.movies().map(m => m.id)).toEqual(store.items().map(m => m.id).sort((a, b) => a - b).sort(() => 0).slice().sort(() => 0));
    expect(component.movies().length).toBe(store.items().length);
  });

  it('re-sorts the list live in both directions as a row is toggled', async () => {
    // Watching the first movie moves it behind the remaining unwatched one.
    items()[0].click();
    await fixture.whenStable();
    expect(rowTitles()).toEqual(['Movie 2', 'Movie 1']);

    // Unwatching it again brings it back to the front.
    items()[1].click();
    await fixture.whenStable();
    expect(rowTitles()).toEqual(['Movie 1', 'Movie 2']);
  });

  it('toggles only the clicked movie, exactly once, when its checkbox is clicked', async () => {
    checkbox().click(); // Movie 1's checkbox on the first row
    await fixture.whenStable();

    // If the row's own click handler also fired, Movie 1 would have been
    // toggled straight back to unwatched.
    expect(isWatched(1)).toBe(true);
    expect(isWatched(2)).toBe(false);
    expect(component.watchedCount()).toBe(1);
  });

  it('toggles the movie rendered in the clicked row after a re-sort', async () => {
    // Watch Movie 1 so the list re-sorts to [Movie 2, Movie 1].
    component.toggleWatched(1);
    await fixture.whenStable();
    expect(rowTitles()).toEqual(['Movie 2', 'Movie 1']);

    // A blank-space click on the first row toggles Movie 2, the movie that row
    // renders - not whichever movie happened to sit at that index before.
    items()[0].click();
    await fixture.whenStable();

    expect(isWatched(2)).toBe(true);
    expect(isWatched(1)).toBe(true);
    // Both watched: the stable sort keeps the store order [Movie 1, Movie 2].
    expect(rowTitles()).toEqual(['Movie 1', 'Movie 2']);
  });
});

