    store.toggleWatched(1); // Movie 1 becomes watched
    await fixture.whenStable();

    const titles = [...el.querySelectorAll('.title-link')].map(a => a.textContent!.trim());
    expect(titles).toEqual(['Movie 2', 'Movie 1']);
  });

